(function(){function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn)}ready(function(){var shell=document.querySelector('.app-shell.dashboard-shell');if(shell){document.body.classList.add('fqx-v121-restaurant-admin-fixed');var btn=document.querySelector('.mq-sidebar-toggle'),ov=document.querySelector('.mq-sidebar-overlay');function toggle(){document.body.classList.toggle('sidebar-open');shell.classList.toggle('sidebar-open')}if(btn&&!btn.dataset.fqx121){btn.dataset.fqx121='1';btn.addEventListener('click',toggle)}if(ov&&!ov.dataset.fqx121){ov.dataset.fqx121='1';ov.addEventListener('click',toggle)}document.querySelectorAll('.dashboard-shell .nav-item').forEach(function(a){a.addEventListener('click',function(){document.body.classList.remove('sidebar-open');shell.classList.remove('sidebar-open')})})}if(location.pathname.replace(/\/$/,'').endsWith('/blog')){document.body.classList.add('fqx-v121-blog-fixed')}})})();
